def paint_core(
    current_frame: Any,
    transitions: list[dict[str, Any]],
    act: Callable[..., None],
    trace: list[str] | None = None,
) -> None:
    """Paint/flood core: infer the fill colour from observed click transitions;
    once confirmed, queue clicks filling the largest remaining background regions;
    before it is confirmed, queue one probe click to elicit the mechanic."""
    frame = np.asarray(current_frame)

    # ------------------------------------------------------------------
    # Infer the background colour.
    # Prefer using observed transitions: the colour that most often disappears
    # when a click occurs is likely the background.  If no such evidence is
    # available fall back to the most common colour in the current frame.
    # ------------------------------------------------------------------
    bg_counts: dict[int, int] = {}
    for t in transitions:
        if t.get("xy") is None:
            continue
        before = np.asarray(t["before"])
        after = np.asarray(t["after"])
        if before.shape != after.shape:
            continue
        diff = before != after
        if not diff.any():
            continue
        olds = before[diff]
        for col in olds.ravel():
            col = int(col)
            bg_counts[col] = bg_counts.get(col, 0) + 1
    if bg_counts:
        bg_guess = max(bg_counts, key=bg_counts.get)
    else:
        flat = frame.ravel()
        bg_guess = int(np.bincount(flat).argmax()) if flat.size else 0

    # ------------------------------------------------------------------
    # Infer the fill colour using the guessed background.
    # ------------------------------------------------------------------
    fill = _infer_fill_color(transitions, background=bg_guess)

    if fill < 0:
        # Fill colour not yet confirmed – probe a single background region.
        if trace is not None:
            trace.append("fill mechanic unconfirmed -> probe 1 region")
        clicks = paint_plan(frame, background=bg_guess, max_clicks=1, trace=trace)

        # If no region was found (e.g. background colour not present), fall back
        # to clicking any cell that is not the guessed background, or the centre.
        if not clicks:
            mask = frame != bg_guess
            if mask.any():
                ys, xs = np.where(mask)
                cy, cx = int(ys[0]), int(xs[0])
                clicks = [(cx, cy)]
                if trace is not None:
                    trace.append("probe fallback -> click non‑bg cell")
            else:
                h, w = frame.shape
                clicks = [(w // 2, h // 2)]
                if trace is not None:
                    trace.append("probe fallback -> click centre")
    else:
        # Fill colour known – compute the true background (most common colour
        # that is not the fill colour).  If everything is already filled we
        # skip any further clicks.
        mask = frame != fill
        if mask.any():
            bg = int(np.bincount(frame[mask].ravel()).argmax())
        else:
            bg = fill

        if bg == fill:
            clicks: list[tuple[int, int]] = []
            if trace is not None:
                trace.append("all cells filled – no clicks")
        else:
            if trace is not None:
                trace.append(f"fill_color={fill} -> fill regions")
            clicks = paint_plan(frame, background=bg, trace=trace)

    for (x, y) in clicks:
        act("CLICK", x, y)
